/**
 * "Verify payment" flag on carrier bills (Ryne 2026-11-09, queue item 15).
 *
 * STATIC, by nature: the set is Ryne's own sheet (not-paid-yet-2026-11-08.xlsx), bills Aljex marked paid that he has
 * not paid. Nothing in the bill rows says so, so the PRO keys ship as a module (`verifyPaymentPros.ts`, regenerated by
 * `scripts/verifyPaymentBills.mjs --emit-module`). A bill is flagged when its shipment number is on the list and the
 * bill is not VOID. Retire this by emptying the module once Ryne has cleared the list.
 */
import { VERIFY_PAYMENT_PROS } from './verifyPaymentPros'

export const VERIFY_PAYMENT_LABEL = 'Verify payment'
export const VERIFY_PAYMENT_NOTE = 'Verify payment: Aljex marked paid, Ryne has not paid it'

const PROS: ReadonlySet<string> = new Set(VERIFY_PAYMENT_PROS)

/** Aljex PROs are digits; a BCAT original may still carry the `L` prefix or trailing spaces. */
export const proKey = (shipmentNumber: string | null | undefined): string => String(shipmentNumber ?? '').trim().replace(/^L/i, '')

export function isVerifyPaymentBill(bill: { shipmentNumber?: string | null; status?: string | null }): boolean {
  return bill.status !== 'VOID' && PROS.has(proKey(bill.shipmentNumber))
}
